import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"30 個 Openstack 經典面試問題和解答 | LCTT x X-CMD","titleTemplate":false,"description":"30 個 Openstack 經典面試問題和解答 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"30 個 Openstack 經典面試問題和解答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"30 個 Openstack 經典面試問題和解答 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181107 Top 30 OpenStack Interview Questions and Answers","title":"30 個 Openstack 經典面試問題和解答","tag":"201812","desc":""},"relativePath":"201812/20181107 Top 30 OpenStack Interview Questions and Answers.md","filePath":"[post].md"}'),c={name:"201812/20181107 Top 30 OpenStack Interview Questions and Answers.md"};function h(k,a,g,b,u,f){const s=o("Link");return r(),d("div",null,[a[20]||(a[20]=l('<h1 id="_30-個-openstack-經典面試問題和解答" tabindex="-1">30 個 Openstack 經典面試問題和解答 <a class="header-anchor" href="#_30-個-openstack-經典面試問題和解答" aria-label="Permalink to “30 個 Openstack 經典面試問題和解答”">​</a></h1><p>現在，大多數公司都試圖將它們的 IT 基礎設施和電信設施遷移到私有云， 如 OpenStack。如果你打算面試 OpenStack 管理員這個崗位，那麼下面列出的這些面試問題可能會幫助你通過面試。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/OpenStack-Interview-Questions.jpg" alt=""></p><h3 id="q-1-説一下-openstack-及其主要組件" tabindex="-1">Q:1 説一下 OpenStack 及其主要組件？ <a class="header-anchor" href="#q-1-説一下-openstack-及其主要組件" aria-label="Permalink to “Q:1 説一下 OpenStack 及其主要組件？”">​</a></h3><p>答： OpenStack 是一系列開源軟件，這些軟件組成了一個雲供給軟件，也就是 OpenStack，意即開源軟件或項目棧。</p><p>下面是 OpenStack 的主要關鍵組件：</p><ul><li><strong>Nova</strong> – 用於在計算級別管理虛擬機，並在計算或管理程序級別執行其他計算任務。</li><li><strong>Neutron</strong> – 為虛擬機、計算和控制節點提供網絡功能。</li><li><strong>Keystone</strong> – 為所有云用户和 OpenStack 雲服務提供身份認證服務。換句話説，我們可以説 Keystone 是一個提供給雲用户和雲服務訪問權限的方法。</li><li><strong>Horizon</strong> – 用於提供圖形用户界面。使用圖形化管理界面可以很輕鬆地完成各種日常操作任務。</li><li><strong>Cinder</strong> – 用於提供塊存儲功能。通常來説 OpenStack 的 Cinder 中集成了 Chef 和 ScaleIO 來共同為計算和控制節點提供塊存儲服務。</li><li><strong>Swift</strong> – 用於提供對象存儲功能。通常來説，Glance 管理的鏡像是存儲在對象存儲空間的。像 ScaleIO 這樣的外部存儲也可以提供對象存儲，可以很容易的集成 Glance 服務。</li><li><strong>Glance</strong> – 用於提供鏡像服務。使用 Glance 的管理平台來上傳和下載雲鏡像。</li><li><strong>Heat</strong> – 用於提供編排服務或功能。使用 Heat 管理平台可以輕鬆地將虛擬機作為堆棧，並且根據需要可以將虛擬機擴展或收縮。</li><li><strong>Ceilometer</strong> – 用於提供計量與監控功能。</li></ul><h3 id="q-2-什麼服務通常在控制節點上運行" tabindex="-1">Q:2 什麼服務通常在控制節點上運行？ <a class="header-anchor" href="#q-2-什麼服務通常在控制節點上運行" aria-label="Permalink to “Q:2 什麼服務通常在控制節點上運行？”">​</a></h3><p>答： 以下服務通常在控制節點上運行：</p><ul><li>認證服務（KeyStone）</li><li>鏡像服務（Glance）</li><li>Nova 服務比如 Nova API、Nova Scheduler 和 Nova DB</li><li>塊存儲和對象存儲服務</li><li>Ceilometer 服務</li><li>MariaDB / MySQL 和 RabbitMQ 服務</li><li>網絡(Neutron)和網絡代理的管理服務</li><li>編排服務（Heat）</li></ul><h3 id="q-3-什麼服務通常在計算節點上運行" tabindex="-1">Q:3 什麼服務通常在計算節點上運行？ <a class="header-anchor" href="#q-3-什麼服務通常在計算節點上運行" aria-label="Permalink to “Q:3 什麼服務通常在計算節點上運行？”">​</a></h3><p>答： 以下服務通常在計算節點運行：</p><ul><li>Nova 計算</li><li>網絡服務，比如 OVS</li></ul><h3 id="q-4-計算節點上虛擬機的默認地址是什麼" tabindex="-1">Q:4 計算節點上虛擬機的默認地址是什麼? <a class="header-anchor" href="#q-4-計算節點上虛擬機的默認地址是什麼" aria-label="Permalink to “Q:4 計算節點上虛擬機的默認地址是什麼?”">​</a></h3><p>答： 虛擬機存儲在計算節點的 <code>/var/lib/nova/instances</code>。</p><h3 id="q-5-glance-鏡像的默認地址是什麼" tabindex="-1">Q:5 Glance 鏡像的默認地址是什麼？ <a class="header-anchor" href="#q-5-glance-鏡像的默認地址是什麼" aria-label="Permalink to “Q:5 Glance 鏡像的默認地址是什麼？”">​</a></h3><p>答： 因為 Glance 服務運行在控制節點上，所以 Glance 鏡像都被存儲在控制節點的 <code>/var/lib/glance/images</code> 文件夾下。</p>',17)),t("p",null,[a[1]||(a[1]=e("想了解更多請訪問：",-1)),i(s,{href:"https://www.linuxtechi.com/create-delete-virtual-machine-command-line-openstack/"},{default:n(()=>[...a[0]||(a[0]=[e("在 OpenStack 中如何使用命令列創建和刪除虛擬機",-1)])]),_:1})]),a[21]||(a[21]=l(`<h3 id="q-6-説一下如何使用命令列啓動一個虛擬機" tabindex="-1">Q:6 説一下如何使用命令列啓動一個虛擬機？ <a class="header-anchor" href="#q-6-説一下如何使用命令列啓動一個虛擬機" aria-label="Permalink to “Q:6 説一下如何使用命令列啓動一個虛擬機？”">​</a></h3><p>答： 我們可以使用如下 OpenStack 命令來啓動一個新的虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openstack server create --flavor {flavor-name} --image {Image-Name-Or-Image-ID}  --nic net-id={Network-ID} --security-group {Security_Group_ID} –key-name {Keypair-Name} &lt;VM_Name&gt;</span></span></code></pre></div><h3 id="q-7-如何在-openstack-中顯示用户的網絡命名空間列表" tabindex="-1">Q:7 如何在 OpenStack 中顯示用户的網絡命名空間列表？ <a class="header-anchor" href="#q-7-如何在-openstack-中顯示用户的網絡命名空間列表" aria-label="Permalink to “Q:7 如何在 OpenStack 中顯示用户的網絡命名空間列表？”">​</a></h3><p>答： 可以使用 <code>ip net ns</code> 命令來列出用户的網絡命名空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# ip netns list</span></span>
<span class="line"><span>qdhcp-a51635b1-d023-419a-93b5-39de47755d2d</span></span>
<span class="line"><span>haproxy</span></span>
<span class="line"><span>vrouter</span></span></code></pre></div><h3 id="q-8-如何在-openstack-中執行網絡命名空間內的命令" tabindex="-1">Q:8 如何在 OpenStack 中執行網絡命名空間內的命令？ <a class="header-anchor" href="#q-8-如何在-openstack-中執行網絡命名空間內的命令" aria-label="Permalink to “Q:8 如何在 OpenStack 中執行網絡命名空間內的命令？”">​</a></h3><p>答： 假設我們想在 <code>qdhcp-a51635b1-d023-419a-93b5-39de47755d2d</code> 網絡命名空間中執行 <code>ifconfig</code> 命令，我們可以執行如下命令。</p><p>命令格式 : <code>ip netns exec {network-space} &lt;command&gt;</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# ip netns exec qdhcp-a51635b1-d023-419a-93b5-39de47755d2d &quot;ifconfig&quot;</span></span></code></pre></div><h3 id="q-9-在-glance-服務中如何使用命令列上傳和下載鏡像" tabindex="-1">Q:9 在 Glance 服務中如何使用命令列上傳和下載鏡像？ <a class="header-anchor" href="#q-9-在-glance-服務中如何使用命令列上傳和下載鏡像" aria-label="Permalink to “Q:9 在 Glance 服務中如何使用命令列上傳和下載鏡像？”">​</a></h3><p>答： Glance 服務中雲鏡像上傳可以使用如下 OpenStack 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack image create --disk-format qcow2 --container-format bare   --public --file {Name-Cloud-Image}.qcow2     &lt;Cloud-Image-Name&gt;</span></span></code></pre></div><p>下載雲鏡像則使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# glance image-download --file &lt;Cloud-Image-Name&gt; --progress  &lt;Image-ID&gt;</span></span></code></pre></div><h3 id="q-10-openstack-如何將虛擬機從錯誤狀態轉換為活動狀態" tabindex="-1">Q:10 OpenStack 如何將虛擬機從錯誤狀態轉換為活動狀態？ <a class="header-anchor" href="#q-10-openstack-如何將虛擬機從錯誤狀態轉換為活動狀態" aria-label="Permalink to “Q:10 OpenStack 如何將虛擬機從錯誤狀態轉換為活動狀態？”">​</a></h3><p>答： 在某些情況下虛擬機可能會進入錯誤狀態，可以使用如下命令將錯誤狀態轉換為活動狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# nova reset-state --active {Instance_id}</span></span></code></pre></div><h3 id="q-11-如何使用命令列來獲取可使用的浮動-ip-列表" tabindex="-1">Q:11 如何使用命令列來獲取可使用的浮動 IP 列表？ <a class="header-anchor" href="#q-11-如何使用命令列來獲取可使用的浮動-ip-列表" aria-label="Permalink to “Q:11 如何使用命令列來獲取可使用的浮動 IP 列表？”">​</a></h3><p>答： 可使用如下命令來顯示可用浮動 IP 列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# openstack ip floating list | grep None | head -10</span></span></code></pre></div><h3 id="q-12-如何在特定可用區域中或在計算主機上配置虛擬機" tabindex="-1">Q:12 如何在特定可用區域中或在計算主機上配置虛擬機？ <a class="header-anchor" href="#q-12-如何在特定可用區域中或在計算主機上配置虛擬機" aria-label="Permalink to “Q:12 如何在特定可用區域中或在計算主機上配置虛擬機？”">​</a></h3><p>答： 假設我們想在 compute-02 中的可用區 NonProduction 上配置虛擬機，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# openstack server create --flavor m1.tiny --image cirros --nic net-id=e0be93b8-728b-4d4d-a272-7d672b2560a6 --security-group NonProd_SG  --key-name linuxtec --availability-zone NonProduction:compute-02  nonprod_testvm</span></span></code></pre></div><h3 id="q-13-如何在特定計算節點上獲取配置的虛擬機列表" tabindex="-1">Q:13 如何在特定計算節點上獲取配置的虛擬機列表？ <a class="header-anchor" href="#q-13-如何在特定計算節點上獲取配置的虛擬機列表" aria-label="Permalink to “Q:13 如何在特定計算節點上獲取配置的虛擬機列表？”">​</a></h3><p>答： 假設我們想要獲取在 compute-0-19 中配置的虛擬機列表，可以使用如下命令：</p><p>命令格式: <code>openstack server list –all-projects –long -c Name -c Host | grep -i {Compute-Node-Name}</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack server list --all-projects --long -c Name -c Host | grep -i  compute-0-19</span></span></code></pre></div><h3 id="q-14-如何使用命令列查看-openstack-實例的控制台日誌" tabindex="-1">Q:14 如何使用命令列查看 OpenStack 實例的控制台日誌？ <a class="header-anchor" href="#q-14-如何使用命令列查看-openstack-實例的控制台日誌" aria-label="Permalink to “Q:14 如何使用命令列查看 OpenStack 實例的控制台日誌？”">​</a></h3><p>答： 使用如下命令可查看實例的控制台日誌。</p><p>首先獲取實例的 ID，然後使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack console log show {Instance-id}</span></span></code></pre></div><h3 id="q-15-如何獲取-openstack-實例的控制台的-url-地址" tabindex="-1">Q:15 如何獲取 OpenStack 實例的控制台的 URL 地址？ <a class="header-anchor" href="#q-15-如何獲取-openstack-實例的控制台的-url-地址" aria-label="Permalink to “Q:15 如何獲取 OpenStack 實例的控制台的 URL 地址？”">​</a></h3><p>答： 可以使用以下 OpenStack 命令從命令列檢索實例的控制台 URL 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack console url show {Instance-id}</span></span></code></pre></div><h3 id="q-16-如何使用命令列創建可啓動的-cinder-block-存儲卷" tabindex="-1">Q:16 如何使用命令列創建可啓動的 cinder / block 存儲卷？ <a class="header-anchor" href="#q-16-如何使用命令列創建可啓動的-cinder-block-存儲卷" aria-label="Permalink to “Q:16 如何使用命令列創建可啓動的 cinder / block 存儲卷？”">​</a></h3><p>答： 假設創建一個 8GB 可啓動存儲卷，可參考如下步驟：</p><ul><li><p>使用如下命令獲取鏡像列表</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ul><p>~# openstack image list | grep -i cirros | 89254d46-a54b-4bc8-8e4d-658287c7ee92 | cirros  | active |</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  *  使用 cirros 鏡像創建 8GB 的可啓動存儲卷</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>~# cinder create --image-id 89254d46-a54b-4bc8-8e4d-658287c7ee92 --display-name cirros-bootable-vol  8</span></span></code></pre></div><h3 id="q-17-如何列出所有在你的-openstack-中創建的項目或用户" tabindex="-1">Q:17 如何列出所有在你的 OpenStack 中創建的項目或用户？ <a class="header-anchor" href="#q-17-如何列出所有在你的-openstack-中創建的項目或用户" aria-label="Permalink to “Q:17 如何列出所有在你的 OpenStack 中創建的項目或用户？”">​</a></h3><p>答： 可以使用如下命令來檢索所有項目和用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack project list --long</span></span></code></pre></div><h3 id="q-18-如何顯示-openstack-服務端點列表" tabindex="-1">Q:18 如何顯示 OpenStack 服務端點列表？ <a class="header-anchor" href="#q-18-如何顯示-openstack-服務端點列表" aria-label="Permalink to “Q:18 如何顯示 OpenStack 服務端點列表？”">​</a></h3><p>答： OpenStack 服務端點被分為 3 類：</p><ul><li>公共端點</li><li>內部端點</li><li>管理端點</li></ul><p>使用如下 OpenStack 命令來查看各種 OpenStack 服務端點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack catalog list</span></span></code></pre></div><p>可通過以下命令來顯示特定服務端點（比如説 keystone）列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack catalog show keystone</span></span></code></pre></div>`,50)),t("p",null,[a[3]||(a[3]=e("想了解更多請訪問：",-1)),i(s,{href:"https://www.linuxtechi.com/step-by-step-instance-creation-flow-in-openstack/"},{default:n(()=>[...a[2]||(a[2]=[e("OpenStack 中的實例創建流程",-1)])]),_:1}),a[4]||(a[4]=e("。",-1))]),a[22]||(a[22]=l(`<h3 id="q-19-在控制節點上你應該按照什麼步驟來重啓-nova-服務" tabindex="-1">Q:19 在控制節點上你應該按照什麼步驟來重啓 nova 服務？ <a class="header-anchor" href="#q-19-在控制節點上你應該按照什麼步驟來重啓-nova-服務" aria-label="Permalink to “Q:19 在控制節點上你應該按照什麼步驟來重啓 nova 服務？”">​</a></h3><p>答： 應該按照如下步驟來重啓 OpenStack 控制節點的 nova 服務：</p><ul><li><code>service nova-api restart</code></li><li><code>service nova-cert restart</code></li><li><code>service nova-conductor restart</code></li><li><code>service nova-consoleauth restart</code></li><li><code>service nova-scheduler restart</code></li></ul><h3 id="q-20-假如計算節點上為數據流量配置了一些-dpdk-端口-你如何檢查-dpdk-端口的狀態呢" tabindex="-1">Q:20 假如計算節點上為數據流量配置了一些 DPDK 端口，你如何檢查 DPDK 端口的狀態呢？ <a class="header-anchor" href="#q-20-假如計算節點上為數據流量配置了一些-dpdk-端口-你如何檢查-dpdk-端口的狀態呢" aria-label="Permalink to “Q:20 假如計算節點上為數據流量配置了一些 DPDK 端口，你如何檢查 DPDK 端口的狀態呢？”">​</a></h3><p>答： 因為我們使用 openvSwitch (OVS) 來配置 DPDK 端口，因此可以使用如下命令來檢查端口的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@compute-0-15:~# ovs-appctl bond/show | grep dpdk</span></span>
<span class="line"><span>active slave mac: 90:38:09:ac:7a:99(dpdk0)</span></span>
<span class="line"><span>slave dpdk0: enabled</span></span>
<span class="line"><span>slave dpdk1: enabled</span></span>
<span class="line"><span>root@compute-0-15:~#</span></span>
<span class="line"><span>root@compute-0-15:~# dpdk-devbind.py --status</span></span></code></pre></div><h3 id="q-21-如何使用命令列在-openstack-中向存在的安全組-sg-安全組-中添加新規則" tabindex="-1">Q:21 如何使用命令列在 OpenStack 中向存在的安全組 SG（安全組）中添加新規則？ <a class="header-anchor" href="#q-21-如何使用命令列在-openstack-中向存在的安全組-sg-安全組-中添加新規則" aria-label="Permalink to “Q:21 如何使用命令列在 OpenStack 中向存在的安全組 SG（安全組）中添加新規則？”">​</a></h3><p>答： 可以使用 <code>neutron</code> 命令向 OpenStack 已存在的安全組中添加新規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# neutron security-group-rule-create --protocol &lt;tcp or udp&gt;  --port-range-min &lt;port-number&gt; --port-range-max &lt;port-number&gt; --direction &lt;ingress or egress&gt;  --remote-ip-prefix &lt;IP-address-or-range&gt; Security-Group-Name</span></span></code></pre></div><h3 id="q-22-如何查看控制節點和計算節點的-ovs-橋配置" tabindex="-1">Q:22 如何查看控制節點和計算節點的 OVS 橋配置？ <a class="header-anchor" href="#q-22-如何查看控制節點和計算節點的-ovs-橋配置" aria-label="Permalink to “Q:22 如何查看控制節點和計算節點的 OVS 橋配置？”">​</a></h3><p>答： 控制節點和計算節點的 OVS 橋配置可使用以下命令來查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# ovs-vsctl show</span></span></code></pre></div><h3 id="q-23-計算節點上的集成橋-br-int-的作用是什麼" tabindex="-1">Q:23 計算節點上的集成橋（br-int）的作用是什麼？ <a class="header-anchor" href="#q-23-計算節點上的集成橋-br-int-的作用是什麼" aria-label="Permalink to “Q:23 計算節點上的集成橋（br-int）的作用是什麼？”">​</a></h3><p>答： 集成橋（br-int）對來自和運行在計算節點上的實例的流量執行 VLAN 標記和取消標記。</p><p>數據包從實例的 n/w 接口發出使用虛擬接口 qvo 通過 Linux 橋（qbr）。qvb 接口是用來連接 Linux 橋的，qvo 接口是用來連接集成橋的。集成橋上的 qvo 端口有一個內部 VLAN 標籤，這個標籤是用於當數據包到達集成橋的時候貼到數據包頭部的。</p><h3 id="q-24-隧道橋-br-tun-在計算節點上的作用是什麼" tabindex="-1">Q:24 隧道橋（br-tun）在計算節點上的作用是什麼？ <a class="header-anchor" href="#q-24-隧道橋-br-tun-在計算節點上的作用是什麼" aria-label="Permalink to “Q:24 隧道橋（br-tun）在計算節點上的作用是什麼？”">​</a></h3><p>答： 隧道橋（br-tun）根據 OpenFlow 規則將 VLAN 標記的流量從集成網橋轉換為隧道 ID。</p><p>隧道橋允許不同網絡的實例彼此進行通信。隧道有利於封裝在非安全網絡上傳輸的流量，它支持兩層網絡，即 GRE 和 VXLAN。</p><h3 id="q-25-外部-ovs-橋-br-ex-的作用是什麼" tabindex="-1">Q:25 外部 OVS 橋（br-ex）的作用是什麼？ <a class="header-anchor" href="#q-25-外部-ovs-橋-br-ex-的作用是什麼" aria-label="Permalink to “Q:25 外部 OVS 橋（br-ex）的作用是什麼？”">​</a></h3><p>答： 顧名思義，此網橋轉發來往網絡的流量，以允許外部訪問實例。br-ex 連接物理接口比如 eth2，這樣用户網絡的浮動 IP 數據從物理網絡接收並路由到用户網絡端口。</p><h3 id="q-26-openstack-網絡中-openflow-規則的作用是什麼" tabindex="-1">Q:26 OpenStack 網絡中 OpenFlow 規則的作用是什麼？ <a class="header-anchor" href="#q-26-openstack-網絡中-openflow-規則的作用是什麼" aria-label="Permalink to “Q:26  OpenStack 網絡中 OpenFlow 規則的作用是什麼？”">​</a></h3><p>答： OpenFlow 規則是一種機制，這種機制定義了一個數據包如何從源到達目的地。OpenFlow 規則存儲在 flow 表中。flow 表是 OpenFlow 交換機的一部分。</p><p>當一個數據包到達交換機就會被第一個 flow 表檢查，如果不匹配 flow 表中的任何入口，那這個數據包就會被丟棄或者轉發到其他 flow 表中。</p><h3 id="q-27-怎樣查看-openflow-交換機的信息-比如端口、表編號、緩存編號等" tabindex="-1">Q:27 怎樣查看 OpenFlow 交換機的信息（比如端口、表編號、緩存編號等）？ <a class="header-anchor" href="#q-27-怎樣查看-openflow-交換機的信息-比如端口、表編號、緩存編號等" aria-label="Permalink to “Q:27 怎樣查看 OpenFlow 交換機的信息（比如端口、表編號、緩存編號等）？”">​</a></h3><p>答： 假如我們要顯示 OpenFlow 交換機的信息（br-int），需要執行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@compute-0-15# ovs-ofctl show br-int</span></span>
<span class="line"><span>OFPT_FEATURES_REPLY (xid=0x2): dpid:0000fe981785c443</span></span>
<span class="line"><span>n_tables:254, n_buffers:256</span></span>
<span class="line"><span>capabilities: FLOW_STATS TABLE_STATS PORT_STATS QUEUE_STATS ARP_MATCH_IP</span></span>
<span class="line"><span>actions: output enqueue set_vlan_vid set_vlan_pcp strip_vlan mod_dl_src mod_dl_dst mod_nw_src mod_nw_dst mod_nw_tos mod_tp_src mod_tp_dst</span></span>
<span class="line"><span> 1(patch-tun): addr:3a:c6:4f:bd:3e:3b</span></span>
<span class="line"><span>     config:     0</span></span>
<span class="line"><span>     state:      0</span></span>
<span class="line"><span>     speed: 0 Mbps now, 0 Mbps max</span></span>
<span class="line"><span> 2(qvob35d2d65-f3): addr:b2:83:c4:0b:42:3a</span></span>
<span class="line"><span>     config:     0</span></span>
<span class="line"><span>     state:      0</span></span>
<span class="line"><span>     current:    10GB-FD COPPER</span></span>
<span class="line"><span>     speed: 10000 Mbps now, 0 Mbps max</span></span>
<span class="line"><span> ………………………………………</span></span></code></pre></div><h3 id="q-28-如何顯示交換機中的所有-flow-的入口" tabindex="-1">Q:28 如何顯示交換機中的所有 flow 的入口？ <a class="header-anchor" href="#q-28-如何顯示交換機中的所有-flow-的入口" aria-label="Permalink to “Q:28 如何顯示交換機中的所有 flow 的入口？”">​</a></h3><p>答： 可以使用命令 <code>ovs-ofctl dump-flows</code> 來查看交換機的 flow 入口。</p><p>假設我們想顯示 OVS 集成橋（br-int）的所有 flow 入口，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@compute01 ~]# ovs-ofctl dump-flows br-int</span></span></code></pre></div><h3 id="q-29-什麼是-neutron-代理-如何顯示所有-neutron-代理" tabindex="-1">Q:29 什麼是 Neutron 代理？如何顯示所有 Neutron 代理？ <a class="header-anchor" href="#q-29-什麼是-neutron-代理-如何顯示所有-neutron-代理" aria-label="Permalink to “Q:29 什麼是 Neutron 代理？如何顯示所有 Neutron 代理？”">​</a></h3><p>答： OpenStack Neutron 服務器充當中心控制器，實際網絡配置是在計算節點或者網絡節點上執行的。Neutron 代理是計算節點或者網絡節點上進行配置更新的軟件實體。Neutron 代理通過 Neuron 服務和消息隊列來和中心 Neutron 服務通信。</p><p>可通過如下命令查看 Neutron 代理列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack network agent list -c ‘Agent type’ -c Host -c Alive -c State</span></span></code></pre></div><h3 id="q-30-cpu-pinning-是什麼" tabindex="-1">Q:30 CPU Pinning 是什麼？ <a class="header-anchor" href="#q-30-cpu-pinning-是什麼" aria-label="Permalink to “Q:30 CPU Pinning 是什麼？”">​</a></h3><p>答： CPU Pinning 是指為某個虛擬機保留物理核心。它也稱為 CPU 隔離或處理器關聯。有兩個目的：</p><ul><li>它確保虛擬機只能在專用核心上運行</li><li>它還確保公共主機進程不在這些核心上運行</li></ul><p>我們也可以認為 Pinning 是物理核心到一個用户虛擬 CPU（vCPU）的一對一映射。</p><hr>`,39)),t("p",null,[a[6]||(a[6]=e("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/openstack-interview-questions-answers/"},{default:n(()=>[...a[5]||(a[5]=[e("https://www.linuxtechi.com/openstack-interview-questions-answers/",-1)])]),_:1})]),t("p",null,[a[11]||(a[11]=e("作者：",-1)),i(s,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[7]||(a[7]=[e("Pradeep Kumar",-1)])]),_:1}),a[12]||(a[12]=e(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[8]||(a[8]=[e("lujun9972",-1)])]),_:1}),a[13]||(a[13]=e(" 譯者：",-1)),i(s,{href:"https://github.com/ScarboroughCoral"},{default:n(()=>[...a[9]||(a[9]=[e("ScarboroughCoral",-1)])]),_:1}),a[14]||(a[14]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[17]||(a[17]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[15]||(a[15]=[e("LCTT",-1)])]),_:1}),a[18]||(a[18]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...a[16]||(a[16]=[e("Linux中國",-1)])]),_:1}),a[19]||(a[19]=e(" 榮譽推出",-1))])])}const y=p(c,[["render",h]]);export{x as __pageData,y as default};
